import{_ as t,o,c as a,a3 as i}from"./chunks/framework.BveOjhN0.js";const g=JSON.parse('{"title":"Credit Notes — User Guide","description":"","frontmatter":{"head":[["meta",{"property":"og:title","content":"Credit Notes — User Guide | EloSync Docs"}],["meta",{"property":"og:description","content":"Official documentation for the EloSync SaaS Platform."}],["meta",{"property":"og:url","content":"https://docs.elosync.com/user-guide/credit-notes"}],["meta",{"property":"og:image","content":"https://docs.elosync.com/og-image.svg"}],["meta",{"name":"twitter:card","content":"summary_large_image"}],["meta",{"name":"twitter:title","content":"Credit Notes — User Guide | EloSync Docs"}],["meta",{"name":"twitter:description","content":"Official documentation for the EloSync SaaS Platform."}],["meta",{"name":"twitter:image","content":"https://docs.elosync.com/og-image.svg"}],["link",{"rel":"canonical","href":"https://docs.elosync.com/user-guide/credit-notes"}]]},"headers":[],"relativePath":"user-guide/credit-notes.md","filePath":"user-guide/credit-notes.md","lastUpdated":1785699544000}'),s={name:"user-guide/credit-notes.md"};function n(r,e,d,l,c,h){return o(),a("div",null,[...e[0]||(e[0]=[i('<h1 id="credit-notes-—-user-guide" tabindex="-1">Credit Notes — User Guide <a class="header-anchor" href="#credit-notes-—-user-guide" aria-label="Permalink to &quot;Credit Notes — User Guide&quot;">​</a></h1><h2 id="who-can-use-credit-notes" tabindex="-1">Who can use Credit Notes <a class="header-anchor" href="#who-can-use-credit-notes" aria-label="Permalink to &quot;Who can use Credit Notes&quot;">​</a></h2><p>Your workspace must have <strong>Invoices</strong> installed first, then the <strong>Credit Notes</strong> module (both free from Marketplace). Marketplace blocks installing Credit Notes until Invoices is entitled. Your role must include the relevant permissions (<code>view</code>, <code>create</code>, <code>update</code>, <code>delete</code>, <code>restore</code>, <code>force.delete</code>, <code>assign</code>, <code>issue</code>, <code>apply</code>, <code>void</code> as needed).</p><p>Without <strong>assign</strong>, you only see credit notes assigned to you.</p><blockquote><p><strong>Not the same as Central Billing → credit notes.</strong> This module credits your own customers&#39; invoices. The platform&#39;s own Central-side credit note ledger (in the platform admin, not here) tracks credits the platform issues to your workspace against its own module-subscription invoices.</p></blockquote><h2 id="list-table" tabindex="-1">List &amp; table <a class="header-anchor" href="#list-table" aria-label="Permalink to &quot;List &amp; table&quot;">​</a></h2><p>Open <strong>Credit Notes</strong> from the sidebar (<strong>Billing</strong>, after Payments). Search by title or number, filter by status or assignee, toggle <strong>My credit notes</strong>, and switch KPI cards (Total, Mine, Draft, Issued, Applied, Applied total) to quick-filter the table.</p><ul><li>Users with <strong>restore</strong> can filter <strong>Active / Include deleted / Deleted only</strong>, then <strong>Restore</strong> a soft-deleted credit note from the row menu</li><li><strong>Delete permanently</strong> requires <code>credit-notes.force.delete</code> — granted to the workspace <strong>owner</strong> by default</li></ul><h2 id="create-a-credit-note" tabindex="-1">Create a credit note <a class="header-anchor" href="#create-a-credit-note" aria-label="Permalink to &quot;Create a credit note&quot;">​</a></h2><ol><li>Click <strong>New credit note</strong></li><li>Pick the <strong>invoice</strong> to credit — the invoice&#39;s total and balance due are shown for reference; currency follows the selected invoice</li><li>Enter a title, issue date, and notes</li><li>Add line items (description, quantity, unit price, tax rate) — subtotal, tax, and total are calculated automatically</li><li>Optionally link a contact or company (when Contacts/Companies is installed) — defaults to the invoice&#39;s own contact/company if left blank</li><li>Optionally set an assignee (requires <strong>assign</strong>)</li><li>Save</li></ol><p>You can also jump to Credit Notes from an invoice&#39;s detail view — the <strong>Credit notes</strong> link filters the table to credit notes issued against that invoice.</p><p>Edit from the row menu or the detail sheet while the credit note is still <strong>Draft</strong>. Editing replaces the full line-item list. After <strong>Issue</strong>, content is locked; use status actions and assignment instead.</p><h2 id="status-workflow" tabindex="-1">Status workflow <a class="header-anchor" href="#status-workflow" aria-label="Permalink to &quot;Status workflow&quot;">​</a></h2><p>A credit note starts in <strong>Draft</strong>. Move it forward with:</p><ul><li><strong>Issue</strong> (<code>draft → issued</code>) — locks the credit note&#39;s content and sets the issue date to today if it wasn&#39;t set</li><li><strong>Apply</strong> (<code>issued → applied</code>) — adds the credit note&#39;s total to the invoice&#39;s <strong>amount credited</strong> and reduces its <strong>balance due</strong>, which can also advance the invoice&#39;s status to <strong>Partial</strong> or <strong>Paid</strong> (same as posting a payment); this is a one-way, terminal action. Blocked if the invoice is no longer Sent or Partial (e.g. it was voided or already paid off), or if the credit note&#39;s total exceeds the invoice&#39;s current balance due</li><li><strong>Void</strong> — available from <strong>Draft</strong> or <strong>Issued</strong>; permanently cancels the credit note before it has been applied. Once <strong>Applied</strong>, a credit note can no longer be voided.</li></ul><p>Invalid transitions (e.g. applying a draft credit note, or voiding an applied one) are rejected with a validation error.</p><h2 id="assignment" tabindex="-1">Assignment <a class="header-anchor" href="#assignment" aria-label="Permalink to &quot;Assignment&quot;">​</a></h2><p>Users with <strong>assign</strong> can set or clear the assignee from the detail sheet or the create/edit form. The assignee receives an in-app notification when someone else assigns them.</p><h2 id="notes-activity" tabindex="-1">Notes &amp; activity <a class="header-anchor" href="#notes-activity" aria-label="Permalink to &quot;Notes &amp; activity&quot;">​</a></h2><ul><li><strong>Notes</strong> — free-form notes on the credit note</li><li><strong>Activity</strong> — timeline of create, update, assignment, issue, apply, void, note, and delete/restore events</li></ul><h2 id="related-invoice" tabindex="-1">Related invoice <a class="header-anchor" href="#related-invoice" aria-label="Permalink to &quot;Related invoice&quot;">​</a></h2><p>Every credit note detail sheet shows the <strong>Invoice</strong> it was issued against, with a link to jump straight to that invoice&#39;s detail view.</p><h2 id="what-s-not-here-yet" tabindex="-1">What&#39;s not here yet <a class="header-anchor" href="#what-s-not-here-yet" aria-label="Permalink to &quot;What&#39;s not here yet&quot;">​</a></h2><p>Refunding an applied credit note, credit note PDFs/e-mail delivery, and standalone credit notes not tied to an invoice are planned but not part of this module yet — see the <a href="/getting-started/product-roadmap">Product Roadmap</a>.</p>',24)])])}const p=t(s,[["render",n]]);export{g as __pageData,p as default};
